from google.cloud import speech

def stream_chunks(audio_chunks, config=None):
    config = config or {}
    client = speech.SpeechClient()
    recognition = speech.RecognitionConfig(encoding=speech.RecognitionConfig.AudioEncoding.LINEAR16,
        sample_rate_hertz=config.get('sample_rate_hz', 16000), language_code=config.get('language_code', 'en-US'))
    streaming = speech.StreamingRecognitionConfig(config=recognition, interim_results=True)
    requests = (speech.StreamingRecognizeRequest(audio_content=chunk) for chunk in audio_chunks)
    for response in client.streaming_recognize(config=streaming, requests=requests):
        for result in response.results:
            if result.alternatives:
                yield {'text': result.alternatives[0].transcript, 'is_final': result.is_final}

from google.cloud import speech

def partial_results(response):
    for result in response.results:
        if result.alternatives:
            yield {'text': result.alternatives[0].transcript, 'is_final': result.is_final}

from google.cloud import speech

def stream_with_language(audio_chunks, language_code='en-US', punctuation=True):
    config = {
        'language_code': language_code,
        'enable_automatic_punctuation': punctuation
    }
    return stream_chunks(audio_chunks, config=config)

from google.cloud import speech

def get_speech_client():
    return speech.SpeechClient()

def get_recognition_config(encoding, sample_rate_hertz, language_code):
    return speech.RecognitionConfig(encoding=encoding, sample_rate_hertz=sample_rate_hertz, language_code=language_code)

def get_streaming_config(recognition_config, interim_results=True):
    return speech.StreamingRecognitionConfig(config=recognition_config, interim_results=interim_results)

from google.cloud.speech import enums

def normalize_response(response):
    return [{'text': result.alternatives[0].transcript, 'is_final': result.is_final} for result in response.results]
